export function installSidePaths(maps){
 // Visible cleared footpaths connect the main road to both side-route gates.
 maps.march2.sidePaths=[{gateId:'fishing-path',points:[[20,8],[20,2]]}];
 maps.scrub2.sidePaths=[{gateId:'rescue-path',points:[[12,24],[12,29]]}];
 maps.scrub2.gates.push({id:'rescue-path',label:'Side path · Marchwood Glade',x:12,y:25,to:'rescueGlade',arrival:[3,17,'right'],door:true});
 maps.march2.gates.push({id:'fishing-path',label:'Side path · Angler’s Reach',x:20,y:7,to:'anglersReach',arrival:[3,17,'right'],door:true});
 maps.scrub2.spots.push({id:'rescue-sign',label:'Marchwood Glade sign',x:10,y:24});
 maps.march2.spots.push({id:'fishing-sign',label:'Angler’s Reach sign',x:18,y:8});
 maps.rescueGlade={name:'Marchwood Glade',bloom:true,terrain:'ridge',road:[[1,17],[12,17],[12,21],[22,21],[22,17],[35,17]],grass:[],props:[{asset:'tent',x:31,y:7,w:6,h:5}],gates:[{id:'rescue-back',label:'Return to Dorelem Scrub',x:1,y:17,to:'scrub2',arrival:[12,24,'up'],door:true}],spots:[{id:'rescue-leader',label:'Dawn Bloom corporal Hasan ibn Yusuf',x:26,y:16,sprite:2},{id:'rescue-scout',label:'Dawn Bloom scout Ali ibn Salim',x:23,y:14,sprite:1},{id:'rescue-kora',label:'Dawn Bloom soldier Maryam bint Ahmad',x:29,y:17,sprite:1},{id:'rescue-sile',label:'Dawn Bloom soldier Hafsa bint Hasan',x:25,y:20,sprite:2},{id:'rescued-soldier',label:'Cornered True Light soldier',x:30,y:15,sprite:0}]};
 maps.anglersReach={name:'Angler’s Reach',bloom:false,terrain:'wetland',road:[[1,17],[13,17],[13,12],[26,12],[26,18],[34,18]],sidePaths:[{gateId:null,points:[[31,18],[31,14]]}],docks:[[27,17,35,19],[30,13,32,16]],grass:[],props:[{asset:'tent',x:17,y:6,w:5,h:4},{asset:'fishingCrate',x:28,y:17,w:1,h:1,decorative:true}],gates:[{id:'fishing-back',label:'Return to Civeton March',x:1,y:17,to:'march2',arrival:[20,8,'down'],door:true}],spots:[{id:'fishing-warden',label:'Angling warden',x:20,y:12,sprite:1},{id:'fishing-cast',label:'Cast from the main pier',x:34,y:18},{id:'fishing-cast-north',label:'Cast from the north jetty',x:31,y:14},{id:'fishing-prizes',label:'Prize board',x:25,y:11},{id:'fishing-rival-mara',label:'Alice Giffard',x:14,y:13,sprite:2},{id:'fishing-rival-ivo',label:'Old Walter FitzHugh',x:29,y:18,sprite:0}]};
}
export function sideFieldSpots(spots,state,room){if(room!=='rescueGlade')return spots;const won=state.sideAdventures?.rescue?.rescued;return spots.map(s=>s.id.startsWith('rescue-')&&s.sprite!==undefined&&won?{...s,label:'Retreating Dawn Bloom soldier'}:s.id==='rescued-soldier'&&won?{...s,label:'Rescued True Light soldier'}:s);}
